"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["99385"],{44207(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.tipo_documento.protecao_obrigatoria","status":422,"titulo":"Classifica\xe7\xe3o, finalidade e hip\xf3tese legal do tipo de documento s\xe3o obrigat\xf3rias"},"descricao":{"codigo":"uniplus.configuracao.tipo_documento.protecao_obrigatoria","requisitos":["UNI-REQ-0183"],"oQueAconteceu":["O cadastro ou a altera\xe7\xe3o de um tipo de documento chegou sem pelo menos um destes\\ndados: a classifica\xe7\xe3o de prote\xe7\xe3o, a finalidade do tratamento ou a hip\xf3tese\\nlegal. A recusa vem na lista `errors` da resposta, com um item para cada dado que\\nfaltou. Nada \xe9 gravado.","Os tr\xeas dados s\xe3o obrigat\xf3rios porque definem quem pode abrir os arquivos que os\\ncandidatos enviam desse tipo. O documento costuma trazer mais do que o dado que\\ncomprova: o laudo traz o hist\xf3rico cl\xednico, e o comprovante de renda familiar\\ntraz dados de outras pessoas. Sem a classifica\xe7\xe3o, o sistema n\xe3o tem como decidir\\nquem pode abri-lo."],"comoResolver":["Envie de novo o cadastro com os tr\xeas dados preenchidos:","- **classifica\xe7\xe3o de prote\xe7\xe3o**, na mesma escala dos dados do candidato: p\xfablico,\\n  interno, pessoal, identificador ou sens\xedvel;\\n- **finalidade do tratamento**, que explica para que o documento \xe9 pedido;\\n- **hip\xf3tese legal**, que fundamenta o tratamento.","Na d\xfavida sobre a classifica\xe7\xe3o de um tipo de documento, consulte o Encarregado pelo Tratamento de Dados Pessoais\\nda Unifesspa antes de cadastr\xe1-lo."],"ondeAparece":["Cadastro de um tipo de documento","Altera\xe7\xe3o de um tipo de documento"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Tipo documento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);